import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner s = new Scanner(System.in);
        int max = s.nextInt(), reserved = s.nextInt(), n = s.nextInt();
        String[] names = new String[n];
        int[] instances = new int[n];
        int totalInstances = 0;
        for (int i = 0; i < n; i++) {
            names[i] = s.next();
            instances[i] = s.nextInt();
            totalInstances += instances[i];
        }
        int budget = max - reserved;
        int per = totalInstances == 0 ? 0 : budget / totalInstances;
        System.out.println("BUDGET " + budget);
        System.out.println("PER_INSTANCE " + per);
        for (int i = 0; i < n; i++) System.out.println(names[i] + " " + instances[i] * per);
        System.out.println("SPARE " + (budget - per * totalInstances));
        System.out.println(totalInstances > 0 && per == 0 ? "INSUFFICIENT" : "OK");
    }
}

