import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int total = sc.nextInt();
        int chunkSize = sc.nextInt();
        int checkpoint = sc.nextInt();
        int failAt = sc.nextInt();
        int processed = 0;

        for (int from = checkpoint + 1; from <= total; from += chunkSize) {
            int to = Math.min(total, from + chunkSize - 1);
            if (failAt >= from && failAt <= to) {
                System.out.println("ROLLBACK " + from + "-" + to);
                break;
            }
            System.out.println("COMMIT " + from + "-" + to);
            checkpoint = to;
            processed += to - from + 1;
        }
        System.out.println("CHECKPOINT " + checkpoint);
        System.out.println("PROCESSED " + processed);
    }
}

