import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        LocalDate lastCompleted = LocalDate.parse(sc.next());
        LocalDate today = LocalDate.parse(sc.next());
        int maxCatchUp = sc.nextInt();
        int runs = 0;
        LocalDate next = lastCompleted.plusDays(1);
        while (!next.isAfter(today) && runs < maxCatchUp) {
            System.out.println("RUN " + next);
            lastCompleted = next;
            next = next.plusDays(1);
            runs++;
        }
        if (runs == 0) System.out.println("UP_TO_DATE");
        long remaining = lastCompleted.isBefore(today)
                ? ChronoUnit.DAYS.between(lastCompleted, today) : 0;
        System.out.println("CHECKPOINT " + lastCompleted);
        System.out.println("REMAINING " + remaining);
    }
}

